//! Replays `fixtures/plugin_cli_go.json` (generated by `reference/plugin_cli` from Go's
//! server binary at v8.0.35, ae3ee3be) with this binary and the same recorder plugin: plugin flags
//! registered before the parse, value errors for them, and runs handed to the plugin
//! (exit code, output, the execute request and the auth files written). The recorded
//! argv and error lines were rewritten to the double-dash form; cases that exercised
//! Go's flag syntax (single dash, `-bool=false`, last value wins, operands) were dropped.

// Native plugins load only on Unix (the host's `native` module).
#![cfg(unix)]

use std::os::unix::fs::PermissionsExt as _;
use std::path::Path;
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

use serde_json::Value;

/// The generator's `lines`: no log lines; after a parse error (exit 2) only
/// the error line.
fn lines(text: &str, exit: i64) -> Vec<String> {
    let log_line = |l: &str| {
        let b = l.as_bytes();
        b.len() > 22 && b[0] == b'[' && b[5] == b'-' && b[8] == b'-' && b[11] == b' ' && b[20] == b']'
    };
    let mut out = Vec::new();
    for line in text.trim_end_matches('\n').split('\n') {
        if line.is_empty() || log_line(line) {
            continue;
        }
        out.push(line.to_owned());
        if exit == 2 {
            break;
        }
    }
    out
}

#[test]
fn plugin_command_line_matches_go() {
    let tmp = Path::new(env!("CARGO_TARGET_TMPDIR"));
    let Some(built) = cpa_plugin::testing::built_plugins(tmp, "plugin_cli::plugin_command_line_matches_go") else {
        return;
    };
    let fixture: Value = serde_json::from_str(include_str!("fixtures/plugin_cli_go.json")).unwrap();
    let mut failures = Vec::new();
    for (index, case) in fixture["cases"].as_array().unwrap().iter().enumerate() {
        let name = case["name"].as_str().unwrap();
        let work = cpa_plugin::testing::scratch(tmp, &format!("plugin-cli-{index}"));
        let dirs = [
            ("PLUGINDIR", work.join("plugins")),
            ("RECDIR", work.join("rec")),
            ("AUTHDIR", work.join("auths")),
        ];
        for (_, dir) in &dirs {
            std::fs::create_dir_all(dir).unwrap();
        }
        std::fs::copy(built.join("recorder.so"), dirs[0].1.join("rec.so")).unwrap();
        let respond = dirs[1].1.join("respond").join("a");
        std::fs::create_dir_all(&respond).unwrap();
        for (method, key) in [
            ("command_line.register", "register"),
            ("command_line.execute", "execute"),
        ] {
            std::fs::write(respond.join(format!("{method}.json")), case[key].as_str().unwrap()).unwrap();
        }
        for (file, body) in case["auths"].as_object().into_iter().flatten() {
            let path = dirs[2].1.join(file);
            std::fs::write(&path, body.as_str().unwrap()).unwrap();
            std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600)).unwrap();
        }
        let config = work.join("config.yaml");
        let mut text = case["config"].as_str().unwrap().to_owned();
        for (key, dir) in &dirs {
            text = text.replace(key, &dir.to_string_lossy());
        }
        std::fs::write(&config, text).unwrap();
        let db = work.join("cook.db");
        let credential_dir = work.join("cook.db.credentials");
        let args: Vec<String> = case["args"]
            .as_array()
            .unwrap()
            .iter()
            .map(|a| a.as_str().unwrap().replace("CONFIG", &config.to_string_lossy()))
            .collect();
        let mut child = Command::new(env!("CARGO_BIN_EXE_cook-router"))
            .args(&args)
            .current_dir(&work)
            .env_clear()
            .env("HOME", &work)
            .env("COOK_DB", &db)
            .env("PATH", "/usr/bin:/bin")
            .env("TZ", "UTC")
            .env("TMPDIR", std::env::temp_dir())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        let deadline = Instant::now() + Duration::from_secs(60);
        while child.try_wait().unwrap().is_none() {
            if Instant::now() > deadline {
                let _ = child.kill();
                panic!("case {name} did not exit");
            }
            std::thread::sleep(Duration::from_millis(20));
        }
        let output = child.wait_with_output().unwrap();
        let normalize = |s: &str| {
            let mut s = s
                .replace(&*credential_dir.to_string_lossy(), "AUTHDIR")
                .replace(&*config.to_string_lossy(), "CONFIG");
            for (key, dir) in &dirs {
                s = s.replace(&*dir.to_string_lossy(), key);
            }
            s.replace(&*work.to_string_lossy(), "WORK")
        };
        let exit = i64::from(output.status.code().unwrap_or(-1));
        let mut request = Value::Null;
        for rec in cpa_server::testing::records(&dirs[1].1.join("a.jsonl")) {
            if rec["method"] == "command_line.execute" {
                let raw: Value = serde_json::from_str(rec["request"].as_str().unwrap()).unwrap();
                assert_eq!(
                    raw["Host"]["AuthDir"],
                    credential_dir.to_string_lossy().as_ref(),
                    "{name}"
                );
                request = serde_json::from_str(&normalize(rec["request"].as_str().unwrap())).unwrap();
                request["Program"] = "PROGRAM".into();
            }
        }
        let mut files = serde_json::Map::new();
        // SQLite materializes credentials beside the private DB; the legacy directory
        // is only the import source. Parse failures may exit before materialization.
        let auth_dir = if credential_dir.is_dir() {
            &credential_dir
        } else {
            &dirs[2].1
        };
        let mut names: Vec<_> = std::fs::read_dir(auth_dir)
            .unwrap()
            .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
            .filter(|name| name != ".initialize.lock")
            .collect();
        names.sort();
        for file in names {
            let path = auth_dir.join(&file);
            let mode = std::fs::metadata(&path).unwrap().permissions().mode() & 0o777;
            let body = std::fs::read_to_string(&path).unwrap();
            files.insert(file, format!("{mode:o} {body}").into());
        }
        let got = serde_json::json!({
            "exit": exit,
            "stdout": lines(&normalize(&String::from_utf8_lossy(&output.stdout)), exit),
            "stderr": lines(&normalize(&String::from_utf8_lossy(&output.stderr)), exit),
            "request": request,
            "files": files,
        });
        let mut want = case["result"].clone();
        // Keep the Go recording intact, but pin deliberate SQLite changes: no YAML
        // backing path, an additional built-in db flag, and materialized auth paths
        // normalized above. Everything else still compares against the recording.
        if let Some(request) = want["request"].as_object_mut() {
            request.insert("ConfigPath".into(), "".into());
            request["Flags"].as_object_mut().unwrap().insert(
                "db".into(),
                serde_json::json!({"Name": "db", "Set": false, "Type": "", "Value": ""}),
            );
        }
        // ponytail: an unknown flag is reported by clap, not with Go's "flag provided but
        // not defined" (the binary's documented flag-parse gap); only the exit code is
        // compared there.
        if want["stderr"][0]
            .as_str()
            .is_some_and(|l| l.starts_with("flag provided but not defined:"))
        {
            want["stderr"] = got["stderr"].clone();
        }
        if want != got {
            failures.push(format!("case {index} ({name}) {args:?}\n  go:   {want}\n  rust: {got}"));
        }
        let _ = std::fs::remove_dir_all(&work);
    }
    assert!(
        failures.is_empty(),
        "{} case(s) differ from Go:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
